reference_solution:
def binary_tree_paths(root):
    answers = []
    def visit(node, path):
        path.append(str(node.val))
        if node.left is None and node.right is None:
            answers.append("->".join(path))
        else:
            if node.left:
                visit(node.left, path)
            if node.right:
                visit(node.right, path)
        path.pop()
    visit(root, [])
    return answers

